CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,name VARCHAR(120),email VARCHAR(160) UNIQUE NOT NULL,password_hash VARCHAR(100) NOT NULL,role TEXT NOT NULL DEFAULT 'student' CHECK(role IN('student','staff','admin')));
CREATE TABLE IF NOT EXISTS courses(id SERIAL PRIMARY KEY,title VARCHAR(160) NOT NULL,description TEXT,price NUMERIC(10,2) NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'INR',active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS payments(id SERIAL PRIMARY KEY,student_id INT NOT NULL REFERENCES users(id),course_id INT NOT NULL REFERENCES courses(id),gateway_order_id VARCHAR(64) UNIQUE NOT NULL,gateway_payment_id VARCHAR(64) UNIQUE,amount NUMERIC(10,2) NOT NULL,currency CHAR(3) NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','paid','failed','cancelled','refunded')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS enrollments(id SERIAL PRIMARY KEY,student_id INT NOT NULL REFERENCES users(id),course_id INT NOT NULL REFERENCES courses(id),payment_id INT REFERENCES payments(id),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','revoked')),enrolled_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(student_id,course_id));
CREATE TABLE IF NOT EXISTS course_batches(id SERIAL PRIMARY KEY,course_id INT NOT NULL REFERENCES courses(id),name VARCHAR(80));
CREATE TABLE IF NOT EXISTS zoom_meetings(id SERIAL PRIMARY KEY,course_id INT NOT NULL REFERENCES courses(id),batch_id INT REFERENCES course_batches(id),zoom_meeting_id VARCHAR(32) UNIQUE NOT NULL,topic VARCHAR(200) NOT NULL,start_time TIMESTAMP NOT NULL,duration INT NOT NULL,timezone VARCHAR(48) NOT NULL,join_url VARCHAR(400),status TEXT NOT NULL DEFAULT 'scheduled' CHECK(status IN('scheduled','cancelled')));
CREATE INDEX IF NOT EXISTS enrollments_student_id_idx ON enrollments(student_id);
CREATE INDEX IF NOT EXISTS zoom_meetings_course_start_idx ON zoom_meetings(course_id,start_time);
